const virtual_device = require('./index')

module.exports = run_scenarios

// runs the three device checks
async function run_scenarios (opts = {}) {
  const document = opts.document || globalThis.document
  const mount = opts.mount || document?.body
  const devices = virtual_device({ document })
  const results = []
  const on_result = opts.on_result
  const device_a = devices.create(device_runtime, { id: 'device-a' })
  const device_b = devices.create(device_runtime, { id: 'device-b' })
  const device_c = devices.create(device_runtime, { id: 'device-c' })
  mount.append(device_a.view, device_b.view, device_c.view)
  try {
    await Promise.all([device_a.ready, device_b.ready, device_c.ready])
    check({ results, on_result, name: 'create three devices', passed: devices.list().length === 3 })
    const link_a = make_link({ port: device_a.port, tx: devices.tx, to: device_a.id, on: { host_ping } })
    const link_b = make_link({ port: device_b.port, tx: devices.tx, to: device_b.id })
    const link_c = make_link({ port: device_c.port, tx: devices.tx, to: device_c.id })

    const pong = await link_a.ask('ping', 'hello')
    check({ results, on_result, name: 'host to child message', passed: pong.data === 'hello' })

    const pong_2 = await link_a.ask('ping', 'again')
    const format = ['head', 'refs', 'type', 'data', 'meta'].every(key => key in pong_2)
    const counted = pong_2.head[0] === 'device-a' && pong_2.head[1] === 'host' && pong_2.head[2] === pong.head[2] + 1
    check({ results, on_result, name: 'message format and counters', passed: format && counted && pong_2.refs.cause[2] === 1 })

    const host_pong = await link_a.ask('ask_host', 'hello')
    check({ results, on_result, name: 'child to host message', passed: host_pong.data === 'host:hello' })

    await link_a.ask('increase')
    await link_a.ask('increase')
    await link_b.ask('increase')
    const device_a_status = await link_a.ask('status')
    const device_b_status = await link_b.ask('status')
    check({ results, on_result, name: 'isolated runtime state', passed: device_a_status.data.count === 2 && device_b_status.data.count === 1 })

    devices.connect(device_a.id, device_b.id)
    devices.connect(device_b.id, device_c.id)
    await link_a.ask('send', { to: device_b.id, data: 'device-a-to-b' })
    await link_b.ask('send', { to: device_c.id, data: 'device-b-to-c' })
    const linked_device_b = await link_b.ask('status')
    const linked_device_c = await link_c.ask('status')
    const device_b_received = linked_device_b.data.messages.some(has_message('device-a', 'device-a-to-b'))
    const device_c_received = linked_device_c.data.messages.some(has_message('device-b', 'device-b-to-c'))
    check({ results, on_result, name: 'linked device routing', passed: device_b_received && device_c_received })

    // device-a is not linked to device-c, so it pretends to be device-b which is
    await link_a.ask('forge', { as: device_b.id, to: device_c.id })
    const forged_a = await link_a.ask('status')
    const forged_c = await link_c.ask('status')
    const forged_blocked = forged_a.data.errors.some(has_error(device_c.id)) && !forged_c.data.messages.some(has_message('device-b', 'forged'))
    check({ results, on_result, name: 'forged sender rejected', passed: forged_blocked })

    devices.disconnect(device_a.id, device_b.id)
    await link_a.ask('send', { to: device_b.id, data: 'blocked' })
    const disconnected = await link_a.ask('status')
    check({ results, on_result, name: 'disconnected route rejected', passed: disconnected.data.errors.some(has_error(device_b.id)) })

    devices.close(device_b.id)
    check({ results, on_result, name: 'close removes device', passed: !devices.get(device_b.id) && devices.list().length === 2 })
    return results
  } finally {
    devices.close_all()
  }
}

/***************************************
DEVICE RUNTIME
***************************************/
// same small api for every device, runs inside the iframe with (port, tx)
function device_runtime (port, tx) {
  const state = { count: 0, messages: [], errors: [] }
  const wait = {}
  const on = { ping, ask_host, increase, send, forge, status, note, error }
  port.addEventListener('message', receive)

  function receive (event) {
    const msg = event.data
    const answer = wait[msg.refs.cause]
    if (answer) return answer(msg)
    on[msg.type]?.(msg)
  }

  function reply (msg, data) { port.postMessage(tx({ to: msg.head[0], type: 'reply', data, refs: { cause: msg.head } })) }

  function ping (msg) { reply(msg, msg.data) }

  function ask_host (msg) {
    const question = tx({ to: 'host', type: 'host_ping', data: msg.data })
    wait[question.head] = answer => reply(msg, answer.data)
    port.postMessage(question)
  }

  function increase (msg) { reply(msg, ++state.count) }

  function send (msg) {
    port.postMessage(tx({ to: msg.data.to, type: 'note', data: msg.data.data }))
    reply(msg)
  }

  // pretends to be another device, the host must refuse it
  function forge (msg) {
    port.postMessage({ ...tx({ to: msg.data.to, type: 'note', data: 'forged' }), head: [msg.data.as, msg.data.to, 0] })
    reply(msg)
  }

  function status (msg) { reply(msg, { count: state.count, messages: state.messages, errors: state.errors }) }

  function note (msg) { state.messages.push({ from: msg.head[0], data: msg.data }) }

  function error (msg) { state.errors.push({ cause: msg.refs.cause, data: msg.data }) }
}

/***************************************
SCENARIO HELPERS
***************************************/
// host side of one device port: ask() resolves with the reply message
function make_link ({ port, tx, to, on = {} }) {
  const wait = {}
  port.addEventListener('message', receive)
  return { ask }

  function ask (type, data) {
    const msg = tx({ to, type, data })
    const answer = new Promise(resolve => { wait[msg.head] = resolve })
    port.postMessage(msg)
    return answer
  }

  function receive (event) {
    const msg = event.data
    if (msg.head[1] !== 'host') return
    const answer = wait[msg.refs.cause]
    delete wait[msg.refs.cause]
    if (answer) return answer(msg)
    on[msg.type]?.(msg, reply)
  }

  function reply (msg, data) { port.postMessage(tx({ to, type: 'reply', data, refs: { cause: msg.head } })) }
}

function host_ping (msg, reply) { reply(msg, `host:${msg.data}`) }

function has_message (from, data) {
  return function matches_message (message) { return message.from === from && message.data === data }
}

function has_error (to) {
  return function matches_error (error) { return error.cause[1] === to }
}

function check ({ results, on_result, name, passed }) {
  if (!passed) throw new Error(`Scenario failed: ${name}`)
  const result = { name, passed }
  results.push(result)
  on_result?.(result)
}
